import React from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  Divider,
  Stack,
  Typography,
} from '@mui/material';
import { Article as ArticleIcon, ArrowBack as ArrowBackIcon } from '@mui/icons-material';
import { Link as RouterLink, useParams } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { usePublicArticleBySlug } from '../hooks/usePublicArticles';
import { BLOG_CATEGORY_LABELS, formatArticleDate } from '../constants/blogArticles';
import MarketingHeading from './shared/MarketingHeading';

const renderArticleBody = (body: string) => body
  .split(/\n{2,}/)
  .map((paragraph) => paragraph.trim())
  .filter(Boolean)
  .map((paragraph, index) => (
    <Typography
      key={`${index}-${paragraph.slice(0, 24)}`}
      variant="body1"
      color="text.secondary"
      sx={{ lineHeight: 1.8, mb: 2, whiteSpace: 'pre-wrap' }}
    >
      {paragraph}
    </Typography>
  ));

const InsightArticlePage: React.FC = () => {
  const theme = useTheme();
  const { slug = '' } = useParams();
  const { article, loading, error } = usePublicArticleBySlug(slug);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error || !article) {
    return (
      <Box sx={{ maxWidth: 760, mx: 'auto', py: { xs: 2, md: 3 } }}>
        <Typography color="error" sx={{ mb: 2 }}>
          {error || 'Article not found'}
        </Typography>
        <Button component={RouterLink} to="/insights" startIcon={<ArrowBackIcon />}>
          Back to insights
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ maxWidth: 760, mx: 'auto', py: { xs: 2, md: 3 } }}>
      <Button
        component={RouterLink}
        to="/insights"
        startIcon={<ArrowBackIcon />}
        sx={{ mb: 2 }}
      >
        All insights
      </Button>

      {article.coverImageUrl ? (
        <Box
          component="img"
          src={article.coverImageUrl}
          alt={article.title}
          sx={{
            width: '100%',
            maxHeight: 320,
            objectFit: 'cover',
            borderRadius: 3,
            mb: 3,
            display: 'block',
          }}
        />
      ) : (
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            height: 160,
            borderRadius: 3,
            mb: 3,
            bgcolor: alpha(theme.palette.primary.main, 0.08),
            color: 'primary.main',
          }}
        >
          <ArticleIcon sx={{ fontSize: 48 }} />
        </Box>
      )}

      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1.5 }}>
        <Chip
          size="small"
          label={BLOG_CATEGORY_LABELS[article.category] || article.category}
          color="primary"
          variant="outlined"
          sx={{ fontWeight: 600 }}
        />
        {article.tags.map((tag) => (
          <Chip key={tag} size="small" label={tag} variant="outlined" />
        ))}
      </Stack>

      <MarketingHeading level="h1" sx={{ mb: 1 }}>
        {article.title}
      </MarketingHeading>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        {formatArticleDate(article.publishedAt || article.createdAt)}
      </Typography>

      <Typography variant="h6" sx={{ fontWeight: 600, mb: 2, lineHeight: 1.5 }}>
        {article.excerpt}
      </Typography>

      <Divider sx={{ mb: 3 }} />

      <Box>{renderArticleBody(article.body)}</Box>
    </Box>
  );
};

export default InsightArticlePage;
